from ute_core.exception import CoreException


class UteCommonDownloaderException(CoreException):
    """Main exception for ute_common_downloader package."""


class ExecutionError(UteCommonDownloaderException):
    """Exception raised when executed command returns code different than 0."""


class FileNotReleasedError(UteCommonDownloaderException):
    """Exception raised when file is not released by the process."""
